package cn.mop.api;

import cn.mop.domain.*;
import java.nio.charset.StandardCharsets;
import java.time.Instant;
import java.util.*;
import org.junit.jupiter.api.*;
import org.springframework.mock.web.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;

/** Mock repositories only: never writes to any business tenant or database. */
class MonitoringOnboardingControllerTest {
    static final String TENANT=MonitoringOnboardingPlannerTest.TENANT,ACTOR="79000000-0000-4000-8000-000000000002",ASSET="79000000-0000-4000-8000-000000000010";
    PlatformRepository repository;MonitoringOnboardingController controller;Membership member;Asset asset;
    @BeforeEach void setup(){repository=mock(PlatformRepository.class);member=new Membership(ACTOR,TENANT,"padmin",7,true);asset=MonitoringOnboardingPlannerTest.asset(ASSET,TENANT,"192.0.2.10");when(repository.membership(ACTOR,TENANT)).thenReturn(Optional.of(member));when(repository.authorizedAsset(TENANT,ACTOR,7,ASSET)).thenReturn(Optional.of(asset));controller=new MonitoringOnboardingController(repository,MonitoringOnboardingPlannerTest.empty());}
    MockHttpServletRequest request(String body){var r=new MockHttpServletRequest("POST","/api/v1/monitoring-onboarding/plans");r.setUserPrincipal(()->ACTOR);r.getSession().setAttribute("mop.tenant_id",TENANT);r.setContentType("application/json");r.setContent(body.getBytes(StandardCharsets.UTF_8));return r;}
    String body(){return "{\"version\":1,\"assets\":[{\"asset_id\":\""+ASSET+"\",\"profiles\":[\"linux-node\"]}]}";}
    Map<?,?> data(Object result){return (Map<?,?>)((Map<?,?>)result).get("data");}
    @Test void catalogIsCurrentAndDoesNotLookUpAssets(){var data=data(controller.presets(request("")));assertEquals("SERVER_PRESET_CATALOG",data.get("source"));assertEquals(false,data.get("network_accessed"));verify(repository,times(2)).membership(ACTOR,TENANT);verifyNoMoreInteractions(repository);}
    @Test void planUsesServerAddressAndRechecksMembershipAndAssetWithoutWrites(){var data=data(controller.plan(request(body())));assertEquals(true,data.get("asset_scope_checked"));var plan=(Map<?,?>)data.get("plan");assertEquals(true,plan.get("valid"));assertEquals(false,plan.get("applied"));assertTrue(MonitoringOnboardingPlannerTest.tree(plan).toString().contains("http://192.0.2.10:9100/metrics"));verify(repository,times(3)).membership(ACTOR,TENANT);verify(repository,times(2)).authorizedAsset(TENANT,ACTOR,7,ASSET);verifyNoMoreInteractions(repository);}
    @Test void repeatedPreparationReturnsSameHashWithoutIdempotencyWrites(){var one=(Map<?,?>)data(controller.plan(request(body()))).get("plan");var two=(Map<?,?>)data(controller.plan(request(body()))).get("plan");assertEquals(one.get("configuration_sha256"),two.get("configuration_sha256"));verify(repository,times(6)).membership(ACTOR,TENANT);verify(repository,times(4)).authorizedAsset(TENANT,ACTOR,7,ASSET);verifyNoMoreInteractions(repository);}
    @Test void readOnlyMemberMayReadCatalogButCannotPrepare(){when(repository.membership(ACTOR,TENANT)).thenReturn(Optional.of(new Membership(ACTOR,TENANT,"padmin",7,true,List.of("assets:read","configurations:read"))));assertDoesNotThrow(()->controller.presets(request("")));assertEquals(403,assertThrows(DomainException.class,()->controller.plan(request(body()))).status);verify(repository,never()).authorizedAsset(anyString(),anyString(),anyLong(),anyString());}
    @Test void nonexistentOrCrossTenantAssetNeverReleasesConfiguration(){when(repository.authorizedAsset(TENANT,ACTOR,7,ASSET)).thenReturn(Optional.empty());assertEquals(404,assertThrows(DomainException.class,()->controller.plan(request(body()))).status);when(repository.authorizedAsset(TENANT,ACTOR,7,ASSET)).thenReturn(Optional.of(MonitoringOnboardingPlannerTest.asset(ASSET,ACTOR,"192.0.2.10")));assertEquals(404,assertThrows(DomainException.class,()->controller.plan(request(body()))).status);}
    @Test void membershipRevocationDuringPlanningDiscardsResult(){when(repository.authorizedAsset(TENANT,ACTOR,7,ASSET)).thenAnswer(invocation->{when(repository.membership(ACTOR,TENANT)).thenReturn(Optional.empty());return Optional.of(asset);});assertEquals(401,assertThrows(DomainException.class,()->controller.plan(request(body()))).status);}
    @Test void assetAddressOrVersionChangeDuringPlanningDiscardsResult(){var changed=new Asset(ASSET,TENANT,asset.name(),asset.type(),"192.0.2.99",asset.siteId(),asset.status(),asset.lifecycleStatus(),asset.source(),null,null,2,Instant.EPOCH,Instant.EPOCH,null,null);when(repository.authorizedAsset(TENANT,ACTOR,7,ASSET)).thenReturn(Optional.of(asset),Optional.of(changed));assertEquals(409,assertThrows(DomainException.class,()->controller.plan(request(body()))).status);}
    @Test void catalogAlsoRechecksCurrentMembership(){when(repository.membership(ACTOR,TENANT)).thenReturn(Optional.of(member),Optional.empty());assertEquals(401,assertThrows(DomainException.class,()->controller.presets(request(""))).status);}
    @Test void malformedSessionAndPermissionCategoryCannotRead(){var r=request("");r.getSession().setAttribute("mop.tenant_id",17);assertEquals(401,assertThrows(DomainException.class,()->controller.presets(r)).status);when(repository.membership(ACTOR,TENANT)).thenReturn(Optional.of(new Membership(ACTOR,TENANT,"padmin",7,true,List.of("assets:read"))));assertEquals(403,assertThrows(DomainException.class,()->controller.presets(request(""))).status);}
    @Test void boundsDuplicateJsonTrailingContentAndOverrideQueriesAreRejected(){for(String text:List.of("{}"," ".repeat(65537),body()+" {}",body().replace("\"version\":1","\"version\":1,\"version\":1"),body().replace("\"assets\":","\"tenant_id\":\"private\",\"assets\":"))){assertEquals(400,assertThrows(DomainException.class,()->controller.plan(request(text))).status);}var r=request(body());r.addParameter("tenant_id",ACTOR);assertEquals(400,assertThrows(DomainException.class,()->controller.plan(r)).status);verify(repository,never()).authorizedAsset(anyString(),anyString(),anyLong(),anyString());}
    @Test void missingCollectorProducesUnappliedPlanNotFalseSuccess(){var data=data(controller.plan(request(body().replace("linux-node","network-snmp"))));var plan=(Map<?,?>)data.get("plan");assertEquals(false,plan.get("valid"));assertNull(plan.get("configuration"));assertEquals(true,data.get("asset_scope_checked"));assertEquals(false,plan.get("applied"));}
    @Test void invalidDefaultsDoNotClaimAssetScopeWasChecked(){String text=body().replace("\"assets\":","\"defaults\":{\"interval_seconds\":5,\"timeout_seconds\":5},\"assets\":");var data=data(controller.plan(request(text)));assertEquals(false,data.get("asset_scope_checked"));verify(repository,never()).authorizedAsset(anyString(),anyString(),anyLong(),anyString());}
    @Test void responseHeadersRemainPrivate(){var response=new MockHttpServletResponse();controller.privateHeaders(response);assertEquals("no-store",response.getHeader("Cache-Control"));assertEquals("no-referrer",response.getHeader("Referrer-Policy"));}
}
